<script setup>
import { onMounted, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const themes=ref([]),active=ref(''),selected=ref(''),config=ref('{}'),loading=ref(false),error=ref(''),notice=ref(''),uploading=ref(false),file=ref(null)
async function load(){loading.value=true;error.value='';try{const d=await props.api('theme/getThemes');themes.value=Object.entries(d.themes||{}).map(([name,config])=>({name,...config}));active.value=d.active||'';if(!selected.value&&themes.value.length)await open(themes.value[0])}catch(e){error.value=e.message}finally{loading.value=false}}
function nameOf(item){return typeof item==='string'?item:(item.name||item.key||'')}
async function open(item){selected.value=nameOf(item);try{const d=await props.api('theme/getThemeConfig',{method:'POST',body:{name:selected.value}});config.value=JSON.stringify(d??{},null,2)}catch(e){error.value=e.message}}
async function switchTheme(){if(!window.confirm(`切换前台主题为“${selected.value}”？`))return;try{await props.api('config/save',{method:'POST',body:{frontend_theme:selected.value}});active.value=selected.value;notice.value='当前主题已切换。';await load()}catch(e){error.value=e.message}}
async function save(){try{const value=JSON.parse(config.value);await props.api('theme/saveThemeConfig',{method:'POST',body:{name:selected.value,config:value}});notice.value='主题配置已保存。'}catch(e){error.value=e instanceof SyntaxError?'主题配置不是有效 JSON。':e.message}}
async function upload(){if(!file.value)return;uploading.value=true;try{const body=new FormData();body.append('file',file.value);await props.api('theme/upload',{method:'POST',body});file.value=null;notice.value='主题包已上传。';await load()}catch(e){error.value=e.message}finally{uploading.value=false}}
async function remove(){const item=themes.value.find(t=>t.name===selected.value);if(!item?.can_delete){error.value='该主题不可删除（系统主题或当前启用主题）。';return}if(!window.confirm(`删除主题“${selected.value}”？`))return;try{await props.api('theme/delete',{method:'POST',body:{name:selected.value}});notice.value='主题已删除。';selected.value='';await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="theme-view"><div class="page-title-row"><div><p class="eyebrow">EXTENSIONS / THEMES</p><h1>主题<span class="title-period">.</span></h1><p class="page-subtitle">管理当前主题、配置 JSON，并上传或删除主题包。</p></div><button class="refresh-button" @click="load">↻ <span>刷新主题</span></button></div><div class="theme-upload data-panel"><div><p class="eyebrow">INSTALL / ZIP</p><h2>上传主题包</h2><p>仅支持 ZIP，最大 10 MB；文件名需使用英文、数字、下划线或中划线。</p></div><input type="file" accept=".zip,application/zip" @change="file=$event.target.files?.[0]||null"><button :disabled="uploading||!file" @click="upload">{{uploading?'上传中…':'上传 ZIP'}}</button></div><p v-if="error" class="notice">{{error}}</p><p v-if="notice" class="notice success">{{notice}}</p><div class="theme-layout"><nav class="data-panel theme-list"><button v-for="item in themes" :key="item.name" :class="{selected:selected===item.name}" @click="open(item)"><span><b>{{item.name}}</b><small>{{item.version||item.description||'前台主题'}}</small></span><i>{{active===item.name?'当前使用':item.is_system?'系统主题':'可管理'}}</i></button><div v-if="!themes.length&&!loading" class="table-state">没有发现主题。</div></nav><article class="data-panel theme-editor"><div class="panel-heading"><div><p class="eyebrow">THEME / CONFIGURATION</p><h2>{{selected||'选择主题'}}</h2></div><span class="status-label">{{active===selected?'当前主题':'未启用'}}</span></div><textarea v-model="config" rows="20" spellcheck="false" :disabled="!selected"></textarea><footer class="config-actions"><button class="danger-action" :disabled="!themes.find(t=>t.name===selected)?.can_delete" @click="remove">删除主题</button><button :disabled="!selected" @click="switchTheme">设为当前主题</button><button class="save-button" :disabled="!selected" @click="save">保存配置</button></footer></article></div></section></template>
